# Let me fix the boundary check
# TL occupies left side (c <= mid-1)
# TR occupies right side (c >= mid)

def tile_podium2(h, w, bg, tl, tr):
    grid = [[bg for _ in range(w)] for _ in range(h)]
    mid = w // 2  # 11 for width 22

    for r in range(h):
        for c in range(w):
            # TL: only affects left side (c < mid), with main diagonal parity
            if c < mid:
                if (c - r) % 2 == 0:
                    dist = c  # horizontal distance from TL corner
                    if dist < mid:
                        grid[r][c] = tl

            # TR: only affects right side (c >= mid), with anti-diagonal parity
            if c >= mid:
                if (w - 1 - c - r) % 2 == 0:
                    dist = w - 1 - c  # horizontal distance from TR corner
                    if dist < w - mid:
                        grid[r][c] = tr

    return grid

