# - Even columns get TL (when within wave width from left)
# - Odd columns get bg (in middle region)
# - Even columns from right edge get TR (when within wave width from right)

# Test input: TL=0 at (0,0), TR=1 at (0,21), bg=8, 14x22

def final_model(h, w, bg, tl, tr):
    grid = [[bg for _ in range(w)] for _ in range(h)]

    wave_width = 7  # From Demo 3 analysis

    # TL: even columns within wave_width from left edge
