        for c in range(wave_width):
            if c % 2 == 0:
                grid[r][c] = tl

    # TR: even columns from right edge, within wave_width from right
    for r in range(h):
        for c in range(w - wave_width, w):
            if (w - 1 - c) % 2 == 0:  # Even distance from right edge
                grid[r][c] = tr

    return grid

